import re, json

WEEKDAYS = {"Monday","Tuesday","Wednesday","Thursday","Friday"}

def parse_close_hour(time_str):
    """Return closing hour as float (24h) for an entry like '6:30AM–6PM'. Return None if Closed/24h logic complicated."""
    if time_str is None:
        return None
    s = time_str.strip()
    if s.lower() == "closed":
        return None
    if "open 24 hours" in s.lower() or s.lower()=="24 hours":
        return 24.0
    # Split on en dash or hyphen
    parts = re.split(r'[–\-]', s)
    if len(parts) < 2:
        return None
    close = parts[-1].strip()
    m = re.match(r'(\d{1,2})(?::(\d{2}))?\s*(AM|PM)', close, re.IGNORECASE)
    if not m:
        return None
    h = int(m.group(1))
    mins = int(m.group(2)) if m.group(2) else 0
    ampm = m.group(3).upper()
    if ampm == "PM" and h != 12:
        h += 12
    if ampm == "AM" and h == 12:
        h = 0
    return h + mins/60.0

def open_after_6pm_weekday(hours_json):
    try:
        h = json.loads(hours_json)
    except Exception:
        return False
    for day, time_str in h:
        if day in WEEKDAYS:
            close = parse_close_hour(time_str)
            if close is not None and close > 18.0:
                return True
    return False

